  "implementation": "def solve(case):\\n    if not isinstance(case, dict) or 'nodes' not in case or 'utility_threshold' not in case:\\n        raise ValueError('Invalid case: missing required fields')\\n    nodes = case['nodes']\\n    threshold = case['utility_threshold']\\n    if not isinstance(nodes, list) or not nodes:\\n        raise ValueError('Invalid case: nodes must be non-empty list')\\n    node_map = {}\\n    children = {}\\n    for node in nodes:\\n        if not isinstance(node, dict):\\n            raise ValueError('Invalid node')\\n        nid = node.get('id')\\n        parent = node.get('parent')\\n        depth = node.get('depth')\\n        removable = node.get('removable')\\n        utility = node.get('utility')\\n        if None in (nid, parent, depth, removable, utility):\\n            raise ValueError('Node missing required field')\\n        if not isinstance(depth, int) or depth < 0:\\n            raise ValueError('Invalid depth')\\n        if not isinstance(removable, bool):\\n            raise ValueError('removable must be bool')\\n        if not isinstance(utility, (int, float)):\\n            raise ValueError('utility must be numeric')\\n        node_map[nid] = node\\n        if parent is not None:\\n            children.setdefault(parent, []).append(nid)\\n    root_id = None\\n    for nid, node in node_map.items():\\n        if node['parent'] is None:\\n            if root_id is not None:\\n                raise ValueError('Multiple roots')\\n            root_id = nid\\n    if root_id is None:\\n        raise ValueError('No root node')\\n    all_ids = list(node_map.keys())\\n    all_ids.sort(key=lambda nid: (-node_map[nid]['depth'], nid))\\n    queue = all_ids[:]\\n    removed = set()\\n    visit_order = []\\n    def sorted_insert(nid):\\n        nd = node_map[nid]['depth']\\n        for i, qid in enumerate(queue):\\n            qd = node_map[qid]['depth']\\n            if nd > qd or (nd == qd and nid < qid):\\n                queue.insert(i, nid)\\n                return\\n        queue.append(nid)\\n    while queue:\\n        nid = queue.pop(0)\\n        visit_order.append(nid)\\n        if nid in removed:\\n            continue\\n        node = node_map[nid]\\n        is_leaf = True\\n        for child_id in children.get(nid, []):\\n            if child_id not in removed:\\n                is_leaf = False\\n                break\\n        if node['removable'] and is_leaf and node['utility'] <= threshold:\\n            removed.add(nid)\\n            parent_id = node['parent']\\n            if parent_id is not None and parent_id not in removed and parent_id not in queue:\\n                sorted_insert(parent_id)\\n    retained_ids = [nid for nid in node_map if nid not in removed]\\n    retained_ids.sort()\\n    return {'retained_ids': retained_ids, 'visit_order': visit_order}"
